-- No lat/lng available from the state-mode listing.
-- Uses source_id='gtn' so it never collides with curated regional seeds.

alter table hotties.facilities
  add column if not exists gtn_id integer,
  add column if not exists is_indoor boolean;

insert into hotties.sources (id, name, booking_url, scraper_type, enabled, notes) values
  ('gtn', 'Global Tennis Network', 'https://www.globaltennisnetwork.com/', 'static', false,
   'Crowdsourced tennis facility directory. Used for state-wide coverage where
    curated sources are unavailable; no lat/lng or booking integration.')
on conflict (id) do update set
  name = excluded.name,
  booking_url = excluded.booking_url,
  notes = excluded.notes;

